use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::task::JoinHandle;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<Box<dyn Fn(&str, EvictionReason) + Send + Sync>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_secs(60),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_secs(5),
            on_evict: None,
        }
    }
}

pub struct PutOptions {
    pub ttl: Option<Duration>,
    pub size: Option<usize>,
}

struct CacheEntry<V> {
    value: V,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
}

#[derive(Debug, Clone, Default)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
}

pub struct FullStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

pub struct LruCache<V> {
    entries: HashMap<String, CacheEntry<V>>,
    access_order: Vec<String>,
    config: CacheConfig,
    current_memory: usize,
    stats: CacheStats,
}

impl<V> LruCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            entries: HashMap::new(),
            access_order: Vec::new(),
            config,
            current_memory: 0,
            stats: CacheStats::default(),
        }
    }

    pub fn get(&mut self, key: &str) -> Option<&V> {
        let now = Instant::now();
        let expired = self.entries.get(key).map(|e| now > e.expires_at);
        match expired {
            None => {
                self.stats.misses += 1;
                None
            }
            Some(true) => {
                self.delete(key, EvictionReason::Expired);
                self.stats.misses += 1;
                None
            }
            Some(false) => {
                {
                    let entry = self.entries.get_mut(key).unwrap();
                    entry.last_accessed = now;
                    entry.access_count += 1;
                }
                self.move_to_front(key);
                self.stats.hits += 1;
                self.entries.get(key).map(|e| &e.value)
            }
        }
    }

    pub fn put(&mut self, key: &str, value: V, options: Option<PutOptions>) {
        let size = options
            .as_ref()
            .and_then(|o| o.size)
            .unwrap_or(std::mem::size_of::<V>());
        let ttl = options
            .as_ref()
            .and_then(|o| o.ttl)
            .unwrap_or(self.config.default_ttl);

        if let Some(old) = self.entries.get(key) {
            self.current_memory -= old.size;
        }

        while self.current_memory + size > self.config.max_memory_bytes && !self.access_order.is_empty()
        {
            self.evict_lru(EvictionReason::Memory);
        }

        while self.entries.len() >= self.config.max_entries && !self.access_order.is_empty() {
            self.evict_lru(EvictionReason::Lru);
        }

        let now = Instant::now();
        let entry = CacheEntry {
            value,
            expires_at: now + ttl,
            size,
            last_accessed: now,
            access_count: 0,
        };

        self.entries.insert(key.to_owned(), entry);
        self.current_memory += size;
        self.move_to_front(key);
    }

    pub fn delete(&mut self, key: &str, reason: EvictionReason) -> bool {
        let entry = self.entries.remove(key);
        match entry {
            None => false,
            Some(e) => {
                self.current_memory -= e.size;
                self.access_order.retain(|k| k != key);
                match reason {
                    EvictionReason::Expired => self.stats.expirations += 1,
                    _ => self.stats.evictions += 1,
                }
                if let Some(ref cb) = self.config.on_evict {
                    cb(key, reason);
                }
                true
            }
        }
    }

    pub fn has(&mut self, key: &str) -> bool {
        let now = Instant::now();
        let expired = self.entries.get(key).map(|e| now > e.expires_at);
        match expired {
            None => false,
            Some(true) => {
                self.delete(key, EvictionReason::Expired);
                false
            }
            Some(false) => true,
        }
    }

    pub fn size(&self) -> usize {
        self.entries.len()
    }

    pub fn memory_usage(&self) -> usize {
        self.current_memory
    }

    pub fn get_stats(&self) -> FullStats {
        FullStats {
            hits: self.stats.hits,
            misses: self.stats.misses,
            evictions: self.stats.evictions,
            expirations: self.stats.expirations,
            size: self.entries.len(),
            memory: self.current_memory,
        }
    }

    pub fn clear(&mut self) {
        let keys: Vec<String> = self.entries.keys().cloned().collect();
        for key in keys {
            self.delete(&key, EvictionReason::Lru);
        }
    }

    pub fn keys(&self) -> &[String] {
        &self.access_order
    }

    pub fn evict_expired(&mut self) {
        let now = Instant::now();
        let expired: Vec<String> = self
            .entries
            .iter()
            .filter(|(_, e)| now > e.expires_at)
            .map(|(k, _)| k.clone())
            .collect();
        for key in expired {
            self.delete(&key, EvictionReason::Expired);
        }
    }

    fn move_to_front(&mut self, key: &str) {
        if let Some(idx) = self.access_order.iter().position(|k| k == key) {
            let k = self.access_order.remove(idx);
            self.access_order.insert(0, k);
        } else {
            self.access_order.insert(0, key.to_owned());
        }
    }

    fn evict_lru(&mut self, reason: EvictionReason) {
        if let Some(oldest) = self.access_order.pop() {
            self.delete(&oldest, reason);
        }
    }
}

/// Start a background eviction loop. Returns a stop flag and join handle.
pub fn start_eviction_loop<V: Send + 'static>(
    cache: Arc<Mutex<LruCache<V>>>,
) -> (Arc<AtomicBool>, JoinHandle<()>) {
    let interval = cache.lock().unwrap().config.eviction_check_interval;
    let stop = Arc::new(AtomicBool::new(false));
    let stop_flag = stop.clone();
    let handle = tokio::spawn(async move {
        while !stop_flag.load(Ordering::Relaxed) {
            tokio::time::sleep(interval).await;
            if stop_flag.load(Ordering::Relaxed) {
                break;
            }
            cache.lock().unwrap().evict_expired();
        }
    });
    (stop, handle)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    fn make_cache(max_entries: usize, ttl_ms: u64) -> LruCache<String> {
        LruCache::new(CacheConfig {
            max_entries,
            default_ttl: Duration::from_millis(ttl_ms),
            ..Default::default()
        })
    }

    #[tokio::test]
    async fn test_basic_get_put() {
        let mut cache = make_cache(3, 100);
        cache.put("a", "hello".into(), None);
        assert_eq!(cache.get("a").map(String::as_str), Some("hello"));
        assert_eq!(cache.size(), 1);
    }

    #[tokio::test]
    async fn test_lru_eviction() {
        let mut cache = make_cache(3, 100);
        cache.put("a", "hello".into(), None);
        cache.put("b", "world".into(), None);
        cache.put("c", "foo".into(), None);
        cache.put("d", "bar".into(), None); // evicts 'a'
        assert!(!cache.has("a"));
        assert!(cache.has("d"));
    }

    #[tokio::test]
    async fn test_ttl_expiration() {
        let mut cache = make_cache(3, 100);
        cache.put(
            "x",
            "temp".into(),
            Some(PutOptions {
                ttl: Some(Duration::from_millis(50)),
                size: None,
            }),
        );
        tokio::time::sleep(Duration::from_millis(80)).await;
        assert!(cache.get("x").is_none());
    }

    #[tokio::test]
    async fn test_access_order() {
        let mut cache = make_cache(3, 1000);
        cache.put("1", "one".into(), None);
        cache.put("2", "two".into(), None);
        cache.put("3", "three".into(), None);
        cache.get("1"); // access '1', making '2' the LRU
        cache.put("4", "four".into(), None); // evicts '2'
        assert!(!cache.has("2"));
        assert!(cache.has("1"));
    }

    #[tokio::test]
    async fn test_stats() {
        let mut cache = make_cache(3, 100);
        cache.put("a", "hello".into(), None);
        cache.put("b", "world".into(), None);
        cache.put("c", "foo".into(), None);
        cache.put("d", "bar".into(), None);

        // hit
        cache.get("d");
        // miss
        cache.get("a");

        let stats = cache.get_stats();
        assert!(stats.hits > 0, "has hits");
        assert!(stats.misses > 0, "has misses");
    }

    #[tokio::test]
    async fn test_eviction_loop() {
        let cache = Arc::new(Mutex::new(LruCache::new(CacheConfig {
            max_entries: 10,
            default_ttl: Duration::from_millis(50),
            eviction_check_interval: Duration::from_millis(30),
            ..Default::default()
        })));
        cache.lock().unwrap().put("e1", "val1".into(), None);
        let (stop, handle) = start_eviction_loop(cache.clone());
        tokio::time::sleep(Duration::from_millis(150)).await;
        assert!(!cache.lock().unwrap().has("e1"), "eviction loop cleared expired");
        stop.store(true, Ordering::Relaxed);
        let _ = handle.await;
    }

    #[tokio::test]
    async fn test_memory_eviction() {
        let mut cache = LruCache::new(CacheConfig {
            max_entries: 100,
            default_ttl: Duration::from_secs(60),
            max_memory_bytes: 100,
            ..Default::default()
        });
        // Each entry with explicit size
        cache.put(
            "a",
            "x".into(),
            Some(PutOptions { ttl: None, size: Some(50) }),
        );
        cache.put(
            "b",
            "y".into(),
            Some(PutOptions { ttl: None, size: Some(50) }),
        );
        // This should evict 'a' due to memory pressure
        cache.put(
            "c",
            "z".into(),
            Some(PutOptions { ttl: None, size: Some(50) }),
        );
        assert!(!cache.has("a"));
        assert!(cache.has("c"));
    }

    #[tokio::test]
    async fn test_clear() {
        let mut cache = make_cache(10, 1000);
        cache.put("a", "1".into(), None);
        cache.put("b", "2".into(), None);
        cache.clear();
        assert_eq!(cache.size(), 0);
        assert_eq!(cache.memory_usage(), 0);
    }

    #[tokio::test]
    async fn test_delete() {
        let mut cache = make_cache(10, 1000);
        cache.put("a", "1".into(), None);
        assert!(cache.delete("a", EvictionReason::Lru));
        assert!(!cache.delete("a", EvictionReason::Lru));
        assert_eq!(cache.size(), 0);
    }

    #[tokio::test]
    async fn test_keys() {
        let mut cache = make_cache(10, 1000);
        cache.put("a", "1".into(), None);
        cache.put("b", "2".into(), None);
        cache.put("c", "3".into(), None);
        // Most recent first
        assert_eq!(cache.keys(), &["c", "b", "a"]);
    }

    #[tokio::test]
    async fn test_on_evict_callback() {
        let evicted = Arc::new(Mutex::new(Vec::new()));
        let evicted2 = evicted.clone();
        let mut cache = LruCache::new(CacheConfig {
            max_entries: 2,
            default_ttl: Duration::from_secs(60),
            on_evict: Some(Box::new(move |key, reason| {
                evicted2.lock().unwrap().push((key.to_owned(), reason));
            })),
            ..Default::default()
        });
        cache.put("a", "1".into(), None);
        cache.put("b", "2".into(), None);
        cache.put("c", "3".into(), None); // evicts 'a'
        let ev = evicted.lock().unwrap();
        assert_eq!(ev.len(), 1);
        assert_eq!(ev[0].0, "a");
        assert_eq!(ev[0].1, EvictionReason::Lru);
    }
}
