```rust
use lru_cache::{CacheConfig, LruCache, PutOptions};
use std::time::Duration;

#[tokio::main]
async fn main() {
    let mut cache: LruCache<String> = LruCache::new(CacheConfig {
        max_entries: 3,
        default_ttl: Duration::from_millis(100),
        ..Default::default()
    });

    cache.put("a", "hello".into(), None);
    assert_eq!(cache.get("a").map(String::as_str), Some("hello"));
    assert_eq!(cache.size(), 1);

    cache.put("b", "world".into(), None);
    cache.put("c", "foo".into(), None);
    cache.put("d", "bar".into(), None);
    assert!(!cache.has("a"), "lru eviction");
    assert!(cache.has("d"), "newest kept");

    cache.clear();
    cache.put(
        "x",
        "temp".into(),
        Some(PutOptions {
            ttl: Some(Duration::from_millis(50)),
            size: None,
        }),
    );
    tokio::time::sleep(Duration::from_millis(80)).await;
    assert!(cache.get("x").is_none(), "ttl expired");

    cache.clear();
    cache.put("1", "one".into(), None);
    cache.put("2", "two".into(), None);
    cache.put("3", "three".into(), None);
    cache.get("1");
    cache.put("4", "four".into(), None);
    assert!(!cache.has("2"), "access order eviction");
    assert!(cache.has("1"), "accessed item kept");

    let stats = cache.get_stats();
    assert!(stats.hits > 0, "has hits");
    assert!(stats.misses > 0, "has misses");

    println!("All tests passed!");
}
